/** Expand templates for a concrete investigation subject. */
export function expandInvestigationTerms(
  engine: SearchEngineEntry,
  vars: Partial<Record<"subject" | "org" | "alias" | "domain" | "jurisdiction" | "ticker" | "year" | "keyword" | "image_url" | "query", string>>
): string[] {
  const replace = (t: string) =>
    t
      .replaceAll("{subject}", vars.subject ?? "{subject}")
      .replaceAll("{org}", vars.org ?? "{org}")
      .replaceAll("{alias}", vars.alias ?? vars.subject ?? "{alias}")
      .replaceAll("{domain}", vars.domain ?? "{domain}")
      .replaceAll("{jurisdiction}", vars.jurisdiction ?? "{jurisdiction}")
      .replaceAll("{ticker}", vars.ticker ?? "{ticker}")
      .replaceAll("{year}", vars.year ?? "{year}")
      .replaceAll("{keyword}", vars.keyword ?? "{keyword}")
      .replaceAll("{image_url}", vars.image_url ?? "{image_url}")
      .replaceAll("{query}", vars.query ?? encodeURIComponent([vars.subject, vars.org].filter(Boolean).join(" ")));
  return engine.investigationSearchTerms.map(replace);
}

/** Build filled query URL for an engine (best-effort). */
export function buildEngineQueryUrl(engine: SearchEngineEntry, query: string): string {
  if (!engine.queryUrlTemplate) return engine.website;
  return engine.queryUrlTemplate.replaceAll("{query}", encodeURIComponent(query)).replaceAll("{image_url}", encodeURIComponent(query));
}

export function enginesByType(type: SearchEngineType): SearchEngineEntry[] {
  return SEARCH_ENGINES.filter((e) => e.type === type);
}

export function activeEngines(): SearchEngineEntry[] {
  return SEARCH_ENGINES.filter((e) => e.status === "active");
}

/** Auto-develop all investigation search terms across all engines for a case subject. */
export function developAllSearchTerms(vars: Parameters<typeof expandInvestigationTerms>[1]): {
  engine: string;
  type: string;
  status: string;
  website: string;
  terms: string[];
  queryUrls: string[];
}[] {
  return SEARCH_ENGINES.map((engine) => {
    const terms = expandInvestigationTerms(engine, vars);
    return {
      engine: engine.name,
      type: engine.type,
      status: engine.status,
      website: engine.website,
      terms,
      queryUrls: terms.map((t) => buildEngineQueryUrl(engine, t)),
    };
  });
}